(()=>{
const pt=document.documentElement.lang==='pt-BR',t=(a,b)=>pt?b:a;
const root=document.createElement('section');root.id='sales-journey';root.className='sales-journey section-shell';
root.innerHTML=`<div class="module-heading"><div><p class="eyebrow">${t('THE COMPLETE COMMERCIAL JOURNEY','A JORNADA COMERCIAL COMPLETA')}</p><h2>${t('From a first hypothesis<br>to a signed agreement.','Da primeira hipótese<br>ao contrato assinado.')}</h2><p>${t('Explore a fictional services opportunity. Each stage explains the objective, work, evidence and decision needed to move forward. This is a process simulation, not a record of a real sale.','Explore uma oportunidade fictícia de serviços. Cada etapa explica objetivo, atividades, evidências e decisão para avançar. É uma simulação de processo, não o registro de uma venda real.')}</p></div><span class="module-badge">${t('FICTIONAL SCENARIO','CENÁRIO FICTÍCIO')}</span></div><div class="journey-layout"><nav id="journey-steps" aria-label="${t('Sales journey stages','Etapas da jornada comercial')}"></nav><div><div class="journey-context"><strong>${t('Example account: Horizon Works','Conta de exemplo: Horizon Works')}</strong><span>${t('Automation discovery · fictional professional services engagement','Discovery de automação · projeto fictício de serviços profissionais')}</span></div><div id="journey-progress" role="status" aria-live="polite"></div><article id="journey-stage"></article><div id="journey-outcome" role="status" aria-live="polite"></div><button type="button" id="journey-reset" class="text-button">${t('Restart the scenario','Reiniciar cenário')}</button></div></div><p class="module-note">${t('Scenario decisions change only this page. No outreach, CRM updates, legal approvals or signatures are performed. Exploring this example does not change the quarterly dashboard below.','As decisões alteram apenas esta página. Nenhuma mensagem, atualização de CRM, aprovação jurídica ou assinatura é realizada. Explorar este exemplo não altera o dashboard trimestral abaixo.')}</p>`;
document.querySelector('#demo').before(root);
const S=(en,br)=>pt?br:en;
const stages=[
  {name:S('Prospecting','Prospecção'),goal:S('Identify an account and a credible reason to talk.','Identificar uma conta e um motivo plausível para conversar.'),actions:S('Define the ideal customer profile, research the account and locate the person responsible for the relevant process.','Definir o perfil de cliente ideal, pesquisar a conta e localizar o responsável pelo processo.'),record:S('Account, role, source and outreach hypothesis.','Conta, função, fonte e hipótese de abordagem.'),gate:S('Account and contact fit are supported by research.','Aderência da conta e do contato sustentada por pesquisa.'),artifact:S('Hypothesis: a process owner may benefit from connecting fragmented information. This is not a confirmed need.','Hipótese: o responsável pelo processo pode se beneficiar da integração de informações fragmentadas. Não é uma necessidade confirmada.'),risk:S('A generic title or a company logo is insufficient evidence of fit.','Um título genérico ou o nome da empresa não comprova aderência.')},
  {name:S('Qualification','Qualificação'),goal:S('Decide whether and how to start a relevant conversation.','Decidir se faz sentido iniciar uma conversa e como fazê-lo.'),actions:S('Check current role, seniority, relevance and existing interaction history. Keep hypotheses separate from customer statements.','Conferir função atual, senioridade, aderência e histórico de interações. Separar hipóteses das falas do cliente.'),record:S('Qualification summary, seniority, driver and evidence source.','Resumo de qualificação, senioridade, driver e fonte da evidência.'),gate:S('The person is relevant and no individual stop or conflicting cadence applies.','O contato é relevante e não há pedido individual de pausa ou cadência conflitante.'),artifact:S('Qualified for an introductory conversation; budget, urgency and buying authority are still unknown.','Qualificado para uma conversa inicial; orçamento, urgência e autoridade de compra ainda são desconhecidos.'),risk:S('Seniority does not automatically mean budget authority.','Senioridade não significa automaticamente autoridade sobre o orçamento.')},
  {name:S('Outreach','Abordagem'),goal:S('Earn a conversation, not force an opportunity.','Conquistar uma conversa, sem presumir uma oportunidade.'),actions:S('Personalize the introduction, choose a suitable channel and manage follow-ups. A reply pauses the sequence and creates a human next action.','Personalizar a apresentação, escolher um canal adequado e acompanhar. Uma resposta pausa a sequência e gera uma próxima ação humana.'),record:S('Message, channel, timestamp, response and next task.','Mensagem, canal, data, resposta e próxima tarefa.'),gate:S('The fictional contact agrees to discovery.','O contato fictício concordou com uma conversa de discovery.'),artifact:S('Example reply: “We can discuss how the process works and assess whether there is a fit.”','Resposta fictícia: “Podemos conversar sobre o processo e avaliar se existe aderência.”'),risk:S('A response is not a qualified opportunity or a purchase commitment.','Uma resposta não equivale a uma oportunidade qualificada ou compromisso de compra.')},
  {name:S('Discovery','Discovery'),goal:S('Understand the problem, impact and decision process.','Entender problema, impacto e processo de decisão.'),actions:S('Explore current workflow, business impact, priorities, stakeholders and timing. Confirm what success would look like.','Explorar processo atual, impacto, prioridades, interlocutores e momento. Confirmar como o sucesso será avaliado.'),record:S('Discovery notes, business problem, stakeholders, open questions and agreed next step.','Notas da reunião, problema de negócio, interlocutores, dúvidas e próximo passo combinado.'),gate:S('The problem and success criteria are confirmed with the stakeholder.','Problema e critérios de sucesso confirmados com o interlocutor.'),artifact:S('Example: compare two workflow alternatives using agreed quality and turnaround criteria. No savings target is assumed.','Exemplo: comparar duas alternativas de processo com critérios de qualidade e prazo acordados. Nenhuma meta de economia é presumida.'),risk:S('A product presentation without questions can miss the actual priority.','Uma apresentação sem investigação pode deixar de identificar a prioridade real.')},
  {name:S('Technical evaluation','Avaliação técnica'),goal:S('Check feasibility and demonstrate what is actually available.','Conferir viabilidade e demonstrar o que está disponível.'),actions:S('Align requirements with specialists. Scope the demo, constraints and acceptance criteria. Use a PoC only when it answers a defined uncertainty.','Alinhar requisitos com especialistas. Delimitar demo, restrições e critérios de aceite. Usar PoC quando ela responder a uma incerteza definida.'),record:S('Technical brief, requirements, risks, readiness and evaluation outcome.','Brief técnico, requisitos, riscos, prontidão e resultado da avaliação.'),gate:S('Technical fit and remaining assumptions have been reviewed.','Aderência técnica e premissas pendentes revisadas.'),artifact:S('Evaluation brief: permissions, integration boundaries, operating capacity, exception handling and review responsibilities.','Brief de avaliação: permissões, limites de integração, capacidade operacional, tratamento de exceções e responsáveis pela revisão.'),risk:S('Do not promise an integration or a working demo before checking readiness.','Não prometer integração ou demonstração funcional sem conferir a prontidão.')},
  {name:S('Proposal','Proposta'),goal:S('Turn the validated scope into a reviewable commercial offer.','Transformar o escopo validado em uma oferta comercial revisável.'),actions:S('Define deliverables, responsibilities, assumptions, exclusions, timeline, pricing and payment conditions. Review delivery capacity and economics.','Definir entregáveis, responsabilidades, premissas, exclusões, prazo, preço e pagamento. Revisar capacidade de entrega e viabilidade econômica.'),record:S('Versioned proposal, scope, commercial assumptions and review history.','Proposta versionada, escopo, premissas comerciais e histórico de revisão.'),gate:S('Scope and commercial conditions are ready for the customer to review.','Escopo e condições comerciais prontos para revisão do cliente.'),artifact:S('Fictional offer: a defined services engagement, milestone-based deliverables and a documented change process. Amounts are illustrative only.','Oferta fictícia: projeto de serviços delimitado, entregáveis por marcos e processo de mudança documentado. Valores são apenas ilustrativos.'),risk:S('Do not confuse hourly rate, total contract value, recognized revenue and cash received.','Não confundir valor-hora, valor total do contrato, receita reconhecida e recebimento.')},
  {name:S('Negotiation','Negociação'),goal:S('Resolve differences while preserving a deliverable agreement.','Resolver divergências preservando um acordo viável para entrega.'),actions:S('Understand objections, review scope/price trade-offs and align approval owners. Record changes without making unsupported commitments.','Entender objeções, revisar trocas entre escopo e preço e alinhar responsáveis por aprovação. Registrar mudanças sem assumir compromissos indevidos.'),record:S('Negotiation log, approved revisions, decision owners and pending items.','Histórico da negociação, revisões aprovadas, decisores e pendências.'),gate:S('The commercial terms and internal approvals are aligned.','Condições comerciais e aprovações internas alinhadas.'),artifact:S('Example decision: reduce scope rather than silently reduce delivery capacity. Document the revised deliverables and assumptions.','Decisão fictícia: reduzir escopo em vez de reduzir silenciosamente a capacidade de entrega. Documentar entregáveis e premissas revisados.'),risk:S('A verbal agreement does not mean the contract is signed.','Um acordo verbal não significa contrato assinado.')},
  {name:S('Contract & signature','Contrato e assinatura'),goal:S('Complete the approved contracting process.','Concluir o processo de contratação aprovado.'),actions:S('Coordinate procurement and legal review, confirm authorized signatories and track the agreed signature process. Check that the contract matches the approved proposal.','Coordenar compras e jurídico, confirmar signatários autorizados e acompanhar a assinatura. Conferir a correspondência entre contrato e proposta aprovada.'),record:S('Approved agreement, version, authorized signatories and signed status.','Contrato aprovado, versão, signatários autorizados e status de assinatura.'),gate:S('Legal/commercial approvals and the fictional signature are confirmed.','Aprovações jurídicas/comerciais e assinatura fictícia confirmadas.'),artifact:S('Simulation only: mark this gate to represent an approved and signed agreement. No document is generated or signed externally.','Somente simulação: validar esta etapa representa um contrato aprovado e assinado. Nenhum documento é gerado ou assinado externamente.'),risk:S('Pipeline value is not revenue. A signature does not itself establish recognized revenue or cash collection.','Pipeline não é receita. A assinatura, por si só, não comprova receita reconhecida ou recebimento.')},
  {name:S('Delivery handoff','Passagem para delivery'),goal:S('Give the delivery team the context and commitments needed to start.','Passar ao time de entrega o contexto e os compromissos para começar.'),actions:S('Review scope, success criteria, responsibilities, milestones, assumptions and risks with delivery. Establish kickoff and account follow-up.','Revisar escopo, critérios de sucesso, responsáveis, marcos, premissas e riscos com delivery. Organizar kickoff e acompanhamento da conta.'),record:S('Handoff checklist, delivery owner, kickoff plan and account follow-up.','Checklist de passagem, responsável pela entrega, plano de kickoff e acompanhamento da conta.'),gate:S('Delivery has received and understood the agreed commitments.','Delivery recebeu e entendeu os compromissos acordados.'),artifact:S('Handoff: agreed outcome, deliverables, exclusions, acceptance criteria, dependencies and escalation path.','Passagem: resultado acordado, entregáveis, exclusões, critérios de aceite, dependências e caminho de escalonamento.'),risk:S('Retention starts with delivering the expectations established during the sale.','A retenção começa pela entrega das expectativas estabelecidas na venda.')}
];
let index=0,completed=new Set(),mode='active';
function draw(){const s=stages[index];document.querySelector('#journey-steps').innerHTML=stages.map((x,i)=>`<button type="button" data-journey-step="${i}" ${i===index?'aria-current="step"':''}><span class="step-state">${completed.has(i)?'✓':String(i+1).padStart(2,'0')}</span><span>${x.name}</span></button>`).join('');document.querySelector('#journey-progress').textContent=t(`${completed.size} of ${stages.length} stage criteria validated`,`${completed.size} de ${stages.length} critérios de etapa validados`);document.querySelector('#journey-stage').innerHTML=`<p class="eyebrow">${t('STAGE','ETAPA')} ${index+1} / ${stages.length}</p><h3>${s.name}</h3><p class="stage-goal">${s.goal}</p><div class="stage-facts"><div><h4>${t('What happens','O que acontece')}</h4><p>${s.actions}</p></div><div><h4>${t('What gets recorded','O que registrar')}</h4><p>${s.record}</p></div></div><div class="sample-artifact"><span>${t('ILLUSTRATIVE RECORD','REGISTRO ILUSTRATIVO')}</span><p>${s.artifact}</p></div><p class="stage-risk"><strong>${t('Watch for:','Ponto de atenção:')}</strong> ${s.risk}</p><label class="stage-gate"><input type="checkbox" id="stage-valid" ${completed.has(index)?'checked':''}><span>${s.gate}</span></label><div class="stage-actions"><button class="primary" type="button" id="stage-advance" ${completed.has(index)?'':'disabled'}>${index===7?t('Simulate signed agreement','Simular contrato assinado'):index===8?t('Complete handoff','Concluir passagem'):t('Validate and advance','Validar e avançar')}</button><button class="secondary" type="button" id="stage-investigate">${t('Need more context','Investigar melhor')}</button><button class="secondary" type="button" id="stage-nurture">${t('Move to nurture','Colocar em nutrição')}</button><button class="text-button" type="button" id="stage-lost">${t('Not a fit','Sem aderência')}</button></div>`;document.querySelector('#stage-valid').onchange=e=>{document.querySelector('#stage-advance').disabled=!e.target.checked};document.querySelector('#stage-advance').onclick=()=>{if(mode!=='active'){setOutcome(t('Resume the scenario before validating a stage.','Retome o cenário antes de validar uma etapa.'));return;}completed.add(index);if(index===7)setOutcome(t('Fictional signature recorded. Continue to delivery handoff.','Assinatura fictícia registrada. Continue para a passagem a delivery.'));else setOutcome('');if(index<8){index++;draw();}else{draw();setOutcome(completed.size===9?t('Journey complete: all nine criteria validated. Signed agreement and delivery handoff simulated.','Jornada concluída: nove critérios validados. Contrato assinado e passagem a delivery simulados.'):t('Handoff criterion saved. Earlier stages still need validation before this can be considered a complete journey.','Critério de passagem salvo. Ainda há etapas anteriores a validar antes de considerar a jornada completa.'));}};document.querySelector('#stage-investigate').onclick=()=>setOutcome(t('Keep the current stage. Record the missing information and arrange the appropriate conversation before advancing.','Mantenha a etapa atual. Registre a informação faltante e combine a conversa necessária antes de avançar.'));document.querySelector('#stage-nurture').onclick=()=>pause('nurture');document.querySelector('#stage-lost').onclick=()=>pause('lost');}
function setOutcome(s){document.querySelector('#journey-outcome').textContent=s;}
function pause(state){mode=state;document.querySelector('#journey-outcome').innerHTML=`<p>${state==='nurture'?t('Scenario paused for nurture. Record the reason and an agreed review point.','Cenário pausado para nutrição. Registre o motivo e um momento de revisão combinado.'):t('Scenario closed as not a fit. Preserve the reason; do not count it as a win.','Cenário encerrado por falta de aderência. Preserve o motivo; não conte como venda ganha.')}</p><button type="button" class="secondary" id="journey-resume">${t('Resume simulation','Retomar simulação')}</button>`;document.querySelector('#journey-resume').onclick=()=>{mode='active';setOutcome(t('Simulation resumed at the same stage.','Simulação retomada na mesma etapa.'));draw();};}
document.querySelector('#journey-steps').onclick=e=>{const b=e.target.closest('[data-journey-step]');if(b){index=Number(b.dataset.journeyStep);draw();if(mode==='active')setOutcome(t('You are exploring this stage. Navigation alone does not validate it.','Você está explorando esta etapa. Navegar não valida o critério.'));}};
document.querySelector('#journey-reset').onclick=()=>{index=0;completed=new Set();mode='active';setOutcome('');draw();};draw();
})();
